let user=null,role='',identity='',tab='calendar',selected='',month=new Date().getMonth(),year=new Date().getFullYear();
const current=()=>accounts.find(a=>a.id===identity);
const visibleStudents=()=>accounts.filter(a=>(role!=='교사'||!activeClass||a.class===activeClass)&&a.role==='학생'&&(role==='관리자'||(role==='학생'?a.id===identity:classesOf(current()).includes(a.class))));
const visibleEvents=()=>events.filter(e=>e.type==='important'?true:e.type==='lesson'?(role==='관리자'||(classesOf(current()).includes(e.class)&&(!activeClass||role!=='교사'||e.class===activeClass))):visibleStudents().some(s=>s.id===e.student));
const sorted=a=>[...a].sort((a,b)=>(a.date+' '+a.time).localeCompare(b.date+' '+b.time));
const label=e=>['lesson','important'].includes(e.type)?e.title:`${e.univ} · ${kinds[e.type]}`;
