function showModal(title,body,foot=''){const d=$('#modal');d.innerHTML=`<div class="card-head"><h2>${title}</h2><button onclick="document.querySelector('#modal').close()" aria-label="닫기">✕</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}`;if(!d.open)d.showModal();}
function render(){if(role==='교사'&&!classesOf(current()).includes(activeClass))activeClass=classesOf(current())[0]||'';const students=visibleStudents(),ve=(tab==='calendar'?filteredCalendarEvents(visibleEvents()):visibleEvents()).filter(e=>!e.inactive),me=current();if(!students.some(a=>a.id===selected))selected=students[0]?.id||'';
$('#app').innerHTML=`<aside><div class="brand"><span>m</span>면접온</div><div class="subtitle">면접 방과후 운영 공간</div><div class="nav-title">WORKSPACE</div><button class="nav ${tab==='calendar'?'active':''}" data-tab="calendar">▦ &nbsp; ${role==='학생'?'나의 달력':'달력'}</button>${role!=='학생'?`<button class="nav ${tab==='students'?'active':''}" data-tab="students">♙ &nbsp; 학생</button><button class="nav ${tab==='afterschool'?'active':''}" data-tab="afterschool">✓ &nbsp; 방과후</button><button class="nav ${tab==='accounts'?'active':''}" data-tab="accounts">⊞ &nbsp; 계정 관리</button>`:''}${role==='학생'?`<button class="nav ${tab==='applications'?'active':''}" data-tab="applications">＋ &nbsp; 대학 일정 입력</button><button class="nav ${tab==='students'?'active':''}" data-tab="students">♙ &nbsp; 나의 대학별 일정</button>`:''}<button class="nav ${tab==='submissions'?'active':''}" data-tab="submissions">↥ &nbsp; 과제 제출</button><button class="nav ${tab==='resources'?'active':''}" data-tab="resources">▤ &nbsp; 자료실</button><div class="aside-bottom"><span class="avatar">${role==='관리자'?'관':esc(me?.name[0])}</span>${role==='관리자'?'관리자':esc(me?.name)}<p>${role==='관리자'?'전체 반 관리':esc(me?.class)} · ${role}</p></div></aside><div class="shell"><header class="topbar"><div class="breadcrumb">면접 방과후 &nbsp; / &nbsp; <strong>${role} 공간</strong></div><div class="demo"><span>${esc(me?.name)} · ${esc(role)}</span><button id="changePassword">비밀번호 변경</button><button id="logout">로그아웃</button></div></header><main><div class="heading"><div><h1>${tab==='submissions'?(role==='학생'?'과제 제출':'과제 제출 현황'):tab==='afterschool'?'방과후 등록 현황':tab==='resources'?'자료실':tab==='calendar'?(role==='학생'?'나의 면접 일정':'우리 반 일정'):tab==='applications'?'대학 일정 입력':tab==='students'?(role==='학생'?'나의 대학별 일정':'학생별 대학 일정'):'계정 관리'}</h1><p class="muted">${tab==='resources'?'면접 준비 자료와 게시글을 함께 공유하세요.':tab==='accounts'?(role==='관리자'?'교사와 학생 계정을 한 번에 등록하세요.':`${esc(me?.class)} 학생 계정을 등록하세요.`):role==='학생'?'대학 일정과 방과후 준비사항를 함께 확인하세요.':`${role==='관리자'?'전체 반':esc(me?.class)}의 면접 준비를 한눈에 확인하세요.`}</p></div>${!['accounts','resources','afterschool','submissions'].includes(tab)&&role!=='학생'?'<div class="actions"><button id="addImportant">＋ 학사일정</button><button id="addUniversity">＋ 대학 일정 등록</button><button class="primary" id="addLesson">＋ 방과후 수업 등록</button></div>':''}</div>${role==='교사'&&!['resources','afterschool','submissions'].includes(tab)?`<div class="class-tabs" aria-label="배정반">${classesOf(current()).map(c=>`<button data-class="${esc(c)}" class="${activeClass===c?'selected':''}" aria-pressed="${activeClass===c}">${esc(c)}</button>`).join('')}</div>`:''}${tab==='submissions'?submissionsView():tab==='afterschool'?afterschoolView():tab==='resources'?resourcesView():tab==='applications'?applicationsView():tab==='accounts'?accountsView():`${stats(students,ve)}${tab==='students'?timelineView(students):calendarView(ve)}`}<p class="notice">등록한 계정과 일정은 저장되며, 배정된 권한에 따라 표시됩니다.</p></main></div>`;
if(tab==='afterschool'){$('#progressClass').onchange=e=>{progressClass=e.target.value;render();};}if($('#addImportant'))$('#addImportant').onclick=()=>importantForm();if(tab==='calendar'){if($('#toggleUniversity'))$('#toggleUniversity').onclick=()=>{showUniversity=!showUniversity;render();};if(role==='교사'&&$('#toggleOtherTeachers'))$('#toggleOtherTeachers').onclick=()=>{showOtherTeachers=!showOtherTeachers;render();};}if(tab==='submissions')bindSubmissions();if(tab==='resources')bindResources();document.querySelectorAll('[data-add-date]').forEach(b=>b.onclick=()=>lessonForm(null,b.dataset.addDate));document.querySelectorAll('[data-day]').forEach(b=>b.onclick=e=>{if(!e.target.closest('button'))lessonForm(null,b.dataset.day);});if(tab==='applications'){bindApplications();bindAvailability();}$('#logout').onclick=logout;$('#changePassword').onclick=()=>passwordForm();if($('#addUniversity'))$('#addUniversity').onclick=()=>universityForm();document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;if(tab==='resources')loadResources();else if(tab==='submissions')loadSubmissions();else render();});if($('#addLesson'))$('#addLesson').onclick=()=>lessonForm();if($('#student'))$('#student').onchange=e=>{selected=e.target.value;render();};if($('#prev'))$('#prev').onclick=()=>changeMonth(-1);if($('#next'))$('#next').onclick=()=>changeMonth(1);if($('#resetMonth'))$('#resetMonth').onclick=()=>{month=new Date().getMonth();year=new Date().getFullYear();render();};document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>detail(b.dataset.event));if($('#template'))$('#template').onclick=downloadTemplate;if($('#upload'))$('#upload').onchange=upload;if($('#manual'))$('#manual').onclick=manual;document.querySelectorAll('.reset-password').forEach(b=>b.onclick=()=>resetPassword(b.dataset.id));document.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>{activeClass=b.dataset.class;selected='';render();});document.querySelectorAll('[data-account-role]').forEach(b=>b.onclick=()=>{accountRole=b.dataset.accountRole;render();});document.querySelectorAll('[data-delete-account]').forEach(b=>b.onclick=()=>deleteAccount(b.dataset.deleteAccount));document.querySelectorAll('[data-edit-classes]').forEach(b=>b.onclick=()=>editClasses(b.dataset.editClasses));
}
function stats(students,ve){const monthly=ve.filter(e=>e.date.startsWith(`${year}-${String(month+1).padStart(2,'0')}`));return `<div class="stats"><div class="stat"><label>${role==='학생'?'지원 대학':'배정 학생'}</label><strong>${role==='학생'?new Set(ve.filter(e=>e.univ).map(e=>e.univ)).size:students.length}<small>${role==='학생'?'개교':'명'}</small></strong></div><div class="stat"><label>${month+1}월 면접 일정</label><strong>${monthly.filter(e=>e.type==='interview').length}<small>건</small></strong></div><div class="stat accent"><label>${month+1}월 방과후 수업</label><strong>${monthly.filter(e=>e.type==='lesson').length}<small>회</small></strong></div></div>`;}
function changeMonth(n){const d=new Date(year,month+n,1);year=d.getFullYear();month=d.getMonth();render();}
function calendarEventLabel(e){
 if(e.type==='important')return e.title;
 if(e.type==='lesson'){const stage=lessonStage(e);return stage==='1차-OT'?'방과후1차-OT':stage==='2차-개별지도'?'방과후2차-'+(e.teacher_name||e.title.replace('2차-개별지도','').trim()||'개별지도'):stage==='3차-모의면접'?'방과후3차-모의면접':'방과후-'+e.title;}
 const name=accounts.find(a=>a.id===e.student)?.name||'',univ=(e.univ||'').replace(/여자대학교$/,'여대').replace(/여자대학$/,'여대').replace(/여자대$/,'여대').replace(/대학교$/,'대');return (role==='학생'?'':name+'-')+univ+' '+(e.type==='first'?'1차 발표':e.type==='final'?'최종 발표':'면접');
}
function calendarView(ve){const start=new Date(year,month,1),offset=start.getDay(),count=Math.ceil((offset+new Date(year,month+1,0).getDate())/7)*7;let cells='';for(let i=0;i<count;i++){const d=new Date(year,month,i-offset+1),key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,es=sorted(ve.filter(e=>e.date===key));cells+=`<div ${role!=='학생'?`data-day="${key}"`: ''} class="day ${d.getMonth()!==month?'outside':''}">${role==='학생'?`<span class="date">${d.getDate()}</span>`:`<button class="date add-date" data-add-date="${key}" aria-label="${key} 방과후 수업 등록">${d.getDate()} <small>＋</small></button>`}${es.map(e=>`<button class="event ${e.type}" data-event="${esc(e.id)}" title="${esc(calendarEventLabel(e))}" aria-label="${esc(calendarEventLabel(e))}">${esc(calendarEventLabel(e))}</button>`).join('')}</div>`;}return `${calendarFilters()}<div class="workspace"><section class="card"><div class="card-head"><div class="month-controls"><h2>${year}년 ${month+1}월</h2><button id="prev" aria-label="이전 달">‹</button><button id="next" aria-label="다음 달">›</button></div><button id="resetMonth">이번 달</button></div><div class="legend">${Object.entries(kinds).map(([k,v])=>`<span><i class="${k}"></i>${v}</span>`).join('')}</div><div class="calendar-box"><div class="week">${['일','월','화','수','목','금','토'].map(d=>`<div>${d}</div>`).join('')}</div><div class="calendar">${cells}</div></div></section>${sideView(ve)}</div>`;}
function sideView(ve){const lessons=sorted(ve.filter(e=>e.type==='lesson'&&e.date.startsWith(`${year}-${String(month+1).padStart(2,'0')}`))),l=lessons[0],interviews=sorted(ve.filter(e=>e.type==='interview'&&e.date.startsWith(`${year}-${String(month+1).padStart(2,'0')}`)));return `<section class="card side-card"><div class="side-content"><div class="eyebrow">AFTER SCHOOL</div><h2 style="margin-top:9px">이번 달 방과후</h2>${l?`<div class="next-lesson"><span class="pill" style="background:#ffebc7;color:#946724">${esc(l.class)}</span><h3>${esc(l.title)}</h3><p class="muted">${esc(l.date.slice(5).replace('-','월 '))}일 · ${esc(l.time)}</p><button data-event="${esc(l.id)}">준비사항 확인하기 →</button></div>`:'<p class="muted">등록된 수업이 없습니다.</p>'}<h2 style="margin-top:28px">${month+1}월 면접</h2>${interviews.slice(0,5).map(e=>`<div class="list-item"><span class="avatar">${Number(e.date.slice(-2))}</span><div>${esc(e.univ)}<small>${esc(accounts.find(a=>a.id===e.student)?.name)} · ${esc(e.time)}</small></div></div>`).join('')||'<p class="muted">면접 일정이 없습니다.</p>'}</div></section>`;}
function detail(id){const e=(tab==='afterschool'?events:visibleEvents()).find(e=>e.id===id);if(!e)return;if(e.type==='important'){importantDetail(e);return;}showModal(e.type==='lesson'?'방과후 수업 · 준비사항':kinds[e.type],`<span class="pill">${e.type==='lesson'?esc(e.class):esc(accounts.find(a=>a.id===e.student)?.name)}</span><h2 style="margin:18px 0 10px">${esc(e.type==='lesson'?e.title:e.univ+' '+e.major)}</h2><p>${esc(e.date)} &nbsp; ${esc(e.time||'시간 미정')}</p>${e.application?`<p>${esc(e.admission)} · ${esc(e.interviewType)}</p><p>${esc(e.result||'')}${e.inactive?'1차 불합격으로 비활성화된 일정입니다.':''}</p><p class="muted">학생의 대학 일정 입력에서 관리하는 일정입니다.</p>`:''}${e.type==='lesson'?`<p class="muted">대상: ${JSON.parse(e.target_ids||'null')===null?'전체':role==='학생'?'나의 소그룹 수업':esc(JSON.parse(e.target_ids).map(id=>accounts.find(a=>a.id===id)?.name||'삭제된 학생').join(', '))}</p><h3 style="font-size:15px;margin-top:24px">수업 전 준비사항</h3><div class="task">${esc(e.task||'등록된 준비사항이 없습니다.')}</div>`:''}${admissionResultForm(e)}`,role!=='학생'&&!e.application?'<button id="deleteEvent">일정 삭제</button><button class="primary" id="editEvent">수정</button>':'');bindAdmissionResult(e);if($('#editEvent'))$('#editEvent').onclick=()=>e.type==='lesson'?lessonForm(e):universityForm(e);if($('#deleteEvent'))$('#deleteEvent').onclick=()=>deleteEvent(e);}

function accountsView(){const list=accounts.filter(a=>role==='관리자'?a.role===accountRole:(a.role==='학생'&&a.class===activeClass));return `<section class="card">${role==='관리자'?`<div class="class-tabs account-tabs">${['교사','학생'].map(r=>`<button data-account-role="${r}" class="${accountRole===r?'selected':''}" aria-pressed="${accountRole===r}">${r} 계정 <span class="pill">${accounts.filter(a=>a.role===r).length}</span></button>`).join('')}</div>`:''}<div class="card-head"><h2>${role==='관리자'?accountRole+' 계정':'우리 반 학생 계정'} <span class="pill">${list.length}명</span></h2><button id="manual">＋ 직접 입력</button></div><div class="upload-box"><h3>엑셀 파일로 계정 일괄 등록</h3><p class="muted">학번 · 이름 · 권한 · 배정반 · 아이디<br>${role==='관리자'?'교사의 배정반은 쉼표로 여러 개 입력할 수 있습니다. 예: 1반, 2반':`${esc(current()?.class)}의 학생만 등록할 수 있습니다.`}</p><div class="actions" style="justify-content:center"><button id="template">↓ 엑셀 양식 다운로드</button><label class="primary" style="padding:10px 15px;border-radius:9px;cursor:pointer">↑ 엑셀 업로드<input id="upload" type="file" accept=".xlsx" style="display:none"></label></div><p class="muted" style="font-size:12px">.xlsx · 최대 5MB / 500명 · 업로드 후 오류와 등록 내용을 확인합니다.</p></div><div class="table-wrap"><table><thead><tr>${['학번','이름','권한','배정반','아이디','비밀번호'].map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${list.map(a=>`<tr><td>${esc(a.number||'—')}</td><td><strong>${esc(a.name)}</strong></td><td><span class="pill">${esc(a.role)}</span></td><td>${esc(a.class)} ${role==='관리자'&&a.role==='교사'?`<button data-edit-classes="${esc(a.id)}">배정반 수정</button>`:''}</td><td>${esc(a.id)}</td><td><div class="actions"><button class="reset-password" data-id="${esc(a.id)}">초기화</button>${role==='관리자'?`<button class="danger" data-delete-account="${esc(a.id)}">계정삭제</button>`:''}</div></td></tr>`).join('')}</tbody></table></div></section>`;}
async function downloadTemplate(){try{const wb=new ExcelJS.Workbook(),ws=wb.addWorksheet('계정 등록');ws.columns=[{header:'학번',key:'number',width:16},{header:'이름',key:'name',width:18},{header:'권한',key:'role',width:14},{header:'배정반',key:'class',width:20},{header:'아이디',key:'id',width:24}];ws.views=[{state:'frozen',ySplit:1}];if(role==='교사'){const options=wb.addWorksheet('배정반 목록');classesOf(current()).forEach((c,i)=>{options.getCell('A'+(i+1)).value=c;});wb.definedNames.add("'배정반 목록'!$A$1:$A$"+classesOf(current()).length,'AssignedClasses');options.state='veryHidden';}ws.getRow(1).eachCell(c=>{c.font={bold:true,color:{argb:'FFFFFFFF'}};c.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF365BEA'}};});for(let r=2;r<=501;r++){ws.getCell(`A${r}`).numFmt='@';ws.getCell(`E${r}`).numFmt='@';ws.getCell(`C${r}`).dataValidation={type:'list',allowBlank:false,formulae:[role==='관리자'?'"교사,학생"':'"학생"'],showErrorMessage:true,errorTitle:'권한을 확인하세요',error:'목록에서 권한을 선택해주세요.',errorStyle:'stop'};if(role==='교사'){ws.getCell(`C${r}`).value='학생';ws.getCell(`D${r}`).value=activeClass||classesOf(current())[0];ws.getCell(`D${r}`).dataValidation={type:'list',formulae:['AssignedClasses'],showErrorMessage:true,error:'본인 배정반만 선택할 수 있습니다.',errorStyle:'stop'};}}const blob=new Blob([await wb.xlsx.writeBuffer()],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='면접온_계정등록양식.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){toast('양식을 준비하지 못했습니다. 다시 시도해주세요.');}}
async function upload(ev){const file=ev.target.files[0];if(!file)return;if(file.size>5*1024*1024){toast('5MB 이하 파일을 선택해주세요.');return;}try{const wb=new ExcelJS.Workbook();await wb.xlsx.load(await file.arrayBuffer());const ws=wb.worksheets[0];if(!ws)throw Error('빈 파일입니다.');const headers=['학번','이름','권한','배정반','아이디'];if(headers.some((h,i)=>ws.getRow(1).getCell(i+1).text.trim()!==h))throw Error('첫 행의 열을 학번, 이름, 권한, 배정반, 아이디 순으로 맞춰주세요.');const rows=[];ws.eachRow((r,n)=>{if(n===1)return;const v=[1,2,3,4,5].map(i=>r.getCell(i).text.trim());if(!v[0]&&!v[1]&&!v[4])return;rows.push({number:v[0],name:v[1],role:v[2],class:v[3],id:v[4],row:n});});if(!rows.length)throw Error('등록할 계정이 없습니다.');if(rows.length>500)throw Error('한 번에 최대 500명까지 등록할 수 있습니다.');previewRows(rows);}catch(e){toast(e.message||'엑셀 파일을 읽지 못했습니다.');}ev.target.value='';}
async function previewRows(rows){let checked;try{checked=(await api('/api/accounts/validate',{method:'POST',body:{rows}})).rows;}catch(e){toast(e.message);return;}const errors=checked.filter(r=>r.error);showModal('계정 등록 미리보기',`<p>${checked.length}명 중 <strong>${errors.length}명 오류</strong> ${errors.length?'· 파일을 수정한 후 다시 업로드해주세요.':'· 아래 계정을 등록할 수 있습니다.'}</p><div class="table-wrap"><table><thead><tr><th>행</th><th>이름</th><th>권한 / 반</th><th>아이디</th><th>검사</th></tr></thead><tbody>${checked.map(a=>`<tr><td>${a.row}</td><td>${esc(a.name)}</td><td>${esc(a.role)} / ${esc(a.class)}</td><td>${esc(a.id)}</td><td class="${a.error?'error':''}">${esc(a.error||'정상')}</td></tr>`).join('')}</tbody></table></div>`,`<button onclick="document.querySelector('#modal').close()">닫기</button>${!errors.length?'<button class="primary" id="confirmImport">계정 등록</button>':''}`);if($('#confirmImport'))$('#confirmImport').onclick=async()=>{const button=$('#confirmImport');button.disabled=true;button.textContent='등록 중…';try{const result=await api('/api/accounts',{method:'POST',body:{rows}});await refreshState();showCredentials(result.credentials);}catch(e){toast(e.message);button.disabled=false;button.textContent='계정 등록';}};}

function manual(){showModal('계정 직접 입력',`<form id="accountForm"><label>학번<input name="number" placeholder="학생 필수 / 교사 생략 가능"></label><label>이름<input name="name" required></label><label>권한<select name="role">${(role==='관리자'?['학생','교사']:['학생']).map(r=>`<option ${r===accountRole?'selected':''}>${r}</option>`).join('')}</select></label><label>배정반${role==='교사'?`<select name="class">${classesOf(current()).map(c=>`<option ${c===activeClass?'selected':''}>${esc(c)}</option>`).join('')}</select>`:'<input name="class" required placeholder="학생: 1반 / 교사: 1반, 2반" maxlength="1700">'}</label><label>아이디<input name="id" required placeholder="영문·숫자·._- 3~40자"></label><button type="submit" class="primary">등록 내용 확인</button></form>`);$('#accountForm').onsubmit=e=>{e.preventDefault();previewRows([Object.fromEntries([...new FormData(e.target)].map(([k,v])=>[k,v.trim()]))]);};}
boot();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'get_visible_interview_schedule',description:'현재 로그인한 계정에 허용된 대학 일정과 방과후 수업을 서버에서 조회합니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async input=>{if(!input||Object.keys(input).length)throw Error('입력 항목이 없어야 합니다.');const state=await api('/api/state');return {role:state.user.role,events:state.events};}});}catch(e){console.warn('WebMCP unavailable');}}

function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function editClasses(id){
 const a=accounts.find(a=>a.id===id);if(role!=='관리자'||a?.role!=='교사')return;
 showModal('교사 배정반 수정',`<p><strong>${esc(a.name)}</strong> · ${esc(a.id)}</p><form id="classesForm"><label>배정반<input name="class" required maxlength="1700" value="${esc(a.class)}" placeholder="예: 1반, 2반"></label><p class="muted">쉼표로 구분해 여러 반을 입력하세요. 같은 반 이름을 배정받은 교사들은 그 반의 학생·일정·과제를 함께 관리합니다.</p><button class="primary" type="submit">배정 저장</button></form>`);
 $('#classesForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await api('/api/accounts/classes',{method:'POST',body:{id,class:new FormData(e.target).get('class')}});$('#modal').close();await refreshState();toast('교사의 배정반을 저장했습니다.');}catch(error){toast(error.message);button.disabled=false;}};
}
function deleteAccount(id){
 const a=accounts.find(a=>a.id===id);if(role!=='관리자'||!a||a.role==='관리자')return;
 showModal('계정삭제',`<p><strong>${esc(a.name)} (${esc(a.id)})</strong> 계정을 삭제하시겠습니까?</p><p>${a.role==='학생'?'대학 일정·개인 수업·진도 기록이 삭제됩니다. 함께 듣는 수업에서는 이 학생만 제외됩니다.':'이 교사가 등록한 것으로 확인되는 대학·방과후·학사일정과 해당 수업 진도도 삭제됩니다. 다른 교사의 수업은 유지됩니다.'}</p><p class="muted">삭제하면 즉시 로그인이 해제되며 되돌릴 수 없습니다.</p>`,'<button id="cancelAccountDelete">취소</button><button class="danger" id="confirmAccountDelete">계정삭제</button>');
 $('#cancelAccountDelete').onclick=()=>$('#modal').close();$('#confirmAccountDelete').onclick=async()=>{const button=$('#confirmAccountDelete');button.disabled=true;try{await api('/api/accounts/delete',{method:'POST',body:{id}});$('#modal').close();await refreshState();toast('계정을 삭제했습니다.');}catch(e){toast(e.message);button.disabled=false;}};
}
async function api(url,{method='GET',body}={}){
 const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),method==='GET'?20000:60000);let response,data;
 try{
  response=await fetch(url,{method,credentials:'same-origin',cache:'no-store',signal:controller.signal,headers:body?{'Content-Type':'application/json','X-Interview-Request':'1'}:{},...(body?{body:JSON.stringify(body)}:{})});
  try{data=await response.json();}catch(error){if(controller.signal.aborted)throw error;throw Error('서버에서 올바른 응답을 받지 못했습니다. 잠시 후 다시 시도해주세요.');}
 }catch(error){if(controller.signal.aborted)throw Error(method==='GET'?'연결이 지연되고 있습니다. 잠시 후 다시 시도해주세요.':'응답이 지연되고 있습니다. 새로고침하여 처리 결과를 확인한 뒤 다시 시도해주세요.');if(!response)throw Error('서버에 연결하지 못했습니다. 연결 상태를 확인한 후 다시 시도해주세요.');throw error;}finally{clearTimeout(timeout);}
 if(!response.ok){if(response.status===401&&url!=='/api/login'){user=null;accounts=[];events=[];$('#modal').close();loginView();}throw Object.assign(Error(data.error||'요청을 처리하지 못했습니다.'),{status:response.status,details:data});}return data;
}
function connectionErrorView(message){
 $('#app').innerHTML=`<div class="login-layout"><div class="login-card"><div class="brand"><span>m</span>면접온</div><h2>연결을 확인해주세요</h2><p class="error" role="alert">${esc(message)}</p><button class="primary" id="retryConnection">다시 연결</button></div></div>`;
 $('#retryConnection').onclick=()=>boot();
}
async function boot(){
 $('#app').innerHTML='<div class="login-layout"><div class="login-card"><div class="brand"><span>m</span>면접온</div><p role="status">로그인 상태를 확인하고 있습니다…</p></div></div>';
 try{const result=await api('/api/me');user=result.user;if(user.mustChangePassword){passwordForm(true);return;}await refreshState();}catch(e){if(e.status===401)loginView();else connectionErrorView(e.message);}
}
async function refreshState(){const data=await api('/api/state');user=data.user;role=user.role;identity=user.id;accounts=data.accounts;events=data.events;applications=data.applications||[];availability=data.availability||[];progress=data.progress||[];render();}
function loginView(message=''){
 $('#app').innerHTML=`<div class="login-layout"><section class="login-intro"><div class="brand"><span>m</span>면접온</div><h1>한 명의 일정부터,<br>우리 반의 면접 준비까지.</h1><p>대학별 일정과 방과후 수업을<br>하나의 공간에서 관리하세요.</p><div class="login-path"><span>1차 발표</span><i></i><span>면접</span><i></i><span>최종 발표</span></div></section><section class="login-card"><div class="eyebrow">INTERVIEW AFTER SCHOOL</div><h2>로그인</h2><p class="muted">발급받은 계정으로 접속해주세요.</p><form id="loginForm"><label>아이디<input name="id" required autocomplete="username" maxlength="40" placeholder="아이디 입력"></label><label>비밀번호<input name="password" type="password" required autocomplete="current-password" maxlength="128" placeholder="비밀번호 입력"></label><p class="error" id="loginError" role="alert">${esc(message)}</p><button class="primary" type="submit">로그인</button></form><p class="muted login-help">계정이나 비밀번호를 잊었다면<br>담당 교사 또는 관리자에게 문의하세요.</p></section></div>`;
 $('#loginForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;button.textContent='로그인 중…';$('#loginError').textContent='';try{const data=Object.fromEntries(new FormData(e.target));const result=await api('/api/login',{method:'POST',body:data});user=result.user;tab='calendar';showOtherTeachers=false;showUniversity=true;progressClass='all';selected='';if(user.mustChangePassword)passwordForm(true);else await refreshState();}catch(error){$('#loginError').textContent=error.message;button.disabled=false;button.textContent='로그인';}};
}
async function logout(){try{await api('/api/logout',{method:'POST',body:{}});user=null;accounts=[];events=[];role='';identity='';$('#modal').close();loginView();}catch(e){toast(e.message);}}
function passwordForm(required=false){
 const form=`<p class="muted">${required?'첫 로그인입니다. 발급받은 임시 비밀번호를 본인 비밀번호로 변경해주세요.':'현재 비밀번호를 확인하고 새 비밀번호로 변경합니다.'}</p><form id="passwordForm"><label>현재 ${required?'임시 ':''}비밀번호<input type="password" name="currentPassword" autocomplete="current-password" maxlength="128" required></label><label>새 비밀번호<input type="password" name="newPassword" autocomplete="new-password" minlength="8" maxlength="128" required placeholder="8자 이상"></label><label>새 비밀번호 확인<input type="password" name="confirmPassword" autocomplete="new-password" minlength="8" maxlength="128" required></label><p class="error" id="passwordError" role="alert"></p><button class="primary" type="submit">비밀번호 변경</button></form>`;
 if(required){$('#app').innerHTML=`<div class="login-layout single"><section class="login-card"><div class="brand"><span>m</span>면접온</div><h2>비밀번호 설정</h2>${form}<button id="backLogout" style="margin-top:16px">로그아웃</button></section></div>`;$('#backLogout').onclick=logout;}else showModal('비밀번호 변경',form);
 $('#passwordForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(data.newPassword!==data.confirmPassword){$('#passwordError').textContent='새 비밀번호가 일치하지 않습니다.';return;}const button=e.target.querySelector('button');button.disabled=true;try{await api('/api/password',{method:'POST',body:data});$('#modal').close();await refreshState();toast('비밀번호를 변경했습니다.');}catch(error){if($('#passwordError'))$('#passwordError').textContent=error.message;button.disabled=false;}};
}
async function saveEvent(form,existing,payload){const button=form.querySelector('button[type="submit"]');button.disabled=true;try{const data=payload||Object.fromEntries(new FormData(form));await api(existing?`/api/events/${existing.id}`:'/api/events',{method:existing?'PUT':'POST',body:data});year=Number(data.date.slice(0,4));month=Number(data.date.slice(5,7))-1;$('#modal').close();await refreshState();toast('일정을 저장했습니다.');}catch(e){toast(e.message);button.disabled=false;}}
function universityForm(existing){
 const students=visibleStudents();if(!students.length){toast('계정 관리에서 학생을 먼저 등록해주세요.');return;}if(role==='학생')return;
 showModal(existing?'대학 일정 수정':'대학 일정 등록',`<form id="universityForm"><label>학생<select name="student">${students.map(s=>`<option value="${esc(s.id)}" ${(existing?.student||selected)===s.id?'selected':''}>${esc(s.number)} ${esc(s.name)} · ${esc(s.class)}</option>`).join('')}</select></label><label>대학교<input name="univ" required maxlength="100" value="${esc(existing?.univ||'')}" placeholder="대학교명"></label><label>학과 / 전형<input name="major" maxlength="100" value="${esc(existing?.major||'')}" placeholder="예: 경영학과 · 학생부종합"></label><label>일정 종류<select name="type">${Object.entries(kinds).filter(([k])=>['first','interview','final'].includes(k)).map(([k,v])=>`<option value="${k}" ${(existing?.type||'interview')===k?'selected':''}>${v}</option>`).join('')}</select></label><div class="actions"><label>날짜<input type="date" name="date" min="2000-01-01" max="2100-12-31" required value="${existing?.date||localDate()}"></label><label>시간<input type="time" name="time" required value="${existing?.time||'09:00'}"></label></div><p class="muted">발표와 면접 일정을 각각 등록하면 학생 탭에서 연결됩니다. 1차 발표가 없는 전형은 면접부터 등록하세요.</p><button class="primary" type="submit">일정 저장</button></form>`);
 $('#universityForm').onsubmit=e=>{e.preventDefault();saveEvent(e.target,existing);};
}
function deleteEvent(event){showModal('일정 삭제',`<p><strong>${esc(label(event))}</strong><br>${esc(event.date)} ${esc(event.time)}</p><p>이 일정을 삭제하시겠습니까?</p>`,'<button id="cancelDelete">취소</button><button class="primary" id="confirmDelete">삭제</button>');$('#cancelDelete').onclick=()=>detail(event.id);$('#confirmDelete').onclick=async()=>{const button=$('#confirmDelete');button.disabled=true;try{await api(`/api/events/${event.id}`,{method:'DELETE',body:{}});$('#modal').close();await refreshState();toast('일정을 삭제했습니다.');}catch(e){toast(e.message);button.disabled=false;}};}
function showCredentials(credentials){
 showModal('계정 발급 완료',`<p>초기 비밀번호는 모든 계정에서 777777입니다. 각 사용자에게 아이디와 함께 전달해주세요.</p><p class="muted">첫 로그인 시 새 비밀번호를 설정해야 합니다.</p><div class="table-wrap"><table><thead><tr><th>이름</th><th>아이디</th><th>임시 비밀번호</th></tr></thead><tbody>${credentials.map(a=>`<tr><td>${esc(a.name)}</td><td>${esc(a.id)}</td><td><code>${esc(a.password)}</code></td></tr>`).join('')}</tbody></table></div>`,'<button class="primary" id="downloadCredentials">발급 내역 엑셀 다운로드</button>');
 $('#downloadCredentials').onclick=async()=>{try{const wb=new ExcelJS.Workbook(),ws=wb.addWorksheet('계정 발급 내역');ws.columns=[{header:'학번',key:'number',width:16},{header:'이름',key:'name',width:18},{header:'권한',key:'role',width:12},{header:'배정반',key:'class',width:20},{header:'아이디',key:'id',width:24},{header:'임시 비밀번호',key:'password',width:26}];ws.addRows(credentials);ws.getRow(1).font={bold:true};const blob=new Blob([await wb.xlsx.writeBuffer()],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='면접온_계정발급내역.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){toast('파일을 만들지 못했습니다. 화면의 발급 정보를 확인해주세요.');}};
}
function resetPassword(id){const a=accounts.find(a=>a.id===id);if(!a)return;showModal('임시 비밀번호 재발급',`<p>${esc(a.name)} (${esc(a.id)})의 비밀번호를 초기화하시겠습니까?</p><p class="muted">비밀번호를 777777로 초기화합니다. 기존 로그인 세션이 만료되며, 다음 로그인 시 비밀번호를 변경해야 합니다.</p>`,'<button id="cancelReset">취소</button><button class="primary" id="confirmReset">임시 비밀번호 발급</button>');$('#cancelReset').onclick=()=>$('#modal').close();$('#confirmReset').onclick=async()=>{const button=$('#confirmReset');button.disabled=true;try{const result=await api('/api/accounts/reset-password',{method:'POST',body:{id}});showCredentials(result.credentials);}catch(e){toast(e.message);button.disabled=false;}};}

function applicationsView(){
 const rows=applications.find(a=>a.student===identity)?.rows||Array.from({length:6},()=>({}));
 const labels={univ:'대학명',admission:'전형',major:'학과',interviewType:'면접유형',firstDate:'1차합격 발표 날짜',interviewDate:'면접 날짜',finalDate:'최종발표 날짜',firstResult:'1차 합격 여부',finalResult:'최종 합격 여부'};
 const input=(i,key,r,type='text')=>`<input aria-label="${i+1}번 ${labels[key]}" name="${i}-${key}" type="${type}" ${type==='date'?'min="2000-01-01" max="2100-12-31"':'maxlength="100"'} value="${esc(r[key]||'')}">`;
 const select=(i,key,r,options)=>`<select aria-label="${i+1}번 ${labels[key]}" name="${i}-${key}"><option value="">${key==='interviewType'?'선택':'미정'}</option>${options.map(v=>`<option ${r[key]===v?'selected':''}>${v}</option>`).join('')}</select>`;
 return `<section class="card"><form id="applicationsForm"><div class="card-head"><div><h2>나의 지원 정보 · 최대 6개</h2><p class="muted">주요 대학을 반드시 하나 선택해주세요. 교사 달력에는 해당 대학만 표시되며, 학생별 상세 화면에는 모든 대학이 표시됩니다. 날짜가 미정이면 비워두세요.</p></div><button type="submit" class="primary">지원 정보 저장</button></div><div class="table-wrap application-scroll"><table class="application-table"><thead><tr>${['지원','주요 대학 (필수)','대학명','전형','학과','면접유형','1차합격 발표 날짜','면접 날짜','최종발표 날짜','1차 합격 여부','최종 합격 여부',''].map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${Array.from({length:6},(_,i)=>{const r=rows[i]||{};return `<tr data-application-row="${i}"><th scope="row">${i+1}</th><td><input type="radio" name="primary" value="${i}" aria-label="${i+1}번 대학을 주요 대학으로 선택" ${r.primary?'checked':''}></td><td>${input(i,'univ',r)}</td><td>${input(i,'admission',r)}</td><td>${input(i,'major',r)}</td><td>${select(i,'interviewType',r,['생기부 기반','교과','제시문'])}</td><td><select aria-label="${i+1}번 1차 발표 방식" name="${i}-direct"><option value="false">1차 발표 있음</option><option value="true" ${r.direct?'selected':''}>바로 면접 응시</option></select>${input(i,'firstDate',r,'date')}</td><td>${input(i,'interviewDate',r,'date')}</td><td>${input(i,'finalDate',r,'date')}</td><td>${select(i,'firstResult',r,['합격','불합격'])}</td><td>${select(i,'finalResult',r,['합격','불합격'])}</td><td><button type="button" data-clear-application="${i}">행 비우기</button></td></tr>`;}).join('')}</tbody></table></div><p class="application-help">바로 면접 응시: 1차 발표 없이 면접부터 표시됩니다.<br>1차 불합격: 면접·최종 발표는 비활성화되며 달력과 면접 건수에서 제외됩니다. 합격 여부를 바꾸면 다시 활성화됩니다.</p><p class="error application-help" id="applicationError" role="alert"></p></form></section>${availabilityFormView()}`;
}
function bindApplications(){
 const form=$('#applicationsForm');
 const sync=()=>{for(let i=0;i<6;i++){const field=k=>form.elements.namedItem(`${i}-${k}`),direct=field('direct').value==='true',failed=!direct&&field('firstResult').value==='불합격';field('firstDate').disabled=direct;field('firstResult').disabled=direct;if(direct){field('firstDate').value='';field('firstResult').value='';}field('finalResult').disabled=failed;if(failed)field('finalResult').value='';for(const k of ['interviewDate','finalDate'])field(k).classList.toggle('inactive-input',failed);form.querySelector(`[data-application-row="${i}"]`).classList.toggle('failed-application',failed);}};
 form.onchange=sync;sync();
 form.querySelectorAll('[data-clear-application]').forEach(b=>b.onclick=()=>{const i=b.dataset.clearApplication;const radio=form.querySelector(`input[name="primary"][value="${i}"]`);if(radio)radio.checked=false;for(const field of form.elements)if(field.name?.startsWith(i+'-'))field.value=field.name.endsWith('-direct')?'false':'';sync();});
 form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type="submit"]');button.disabled=true;$('#applicationError').textContent='';const rows=Array.from({length:6},(_,i)=>{const r={};for(const key of ['univ','admission','major','interviewType','firstDate','interviewDate','finalDate','firstResult','finalResult'])r[key]=form.elements.namedItem(`${i}-${key}`).value;r.direct=form.elements.namedItem(`${i}-direct`).value==='true';r.primary=form.elements.namedItem('primary').value===String(i);return r;});try{if(rows.some(r=>r.univ.trim())&&rows.filter(r=>r.primary).length!==1)throw Error('주요 대학을 반드시 하나 선택해주세요.');await api('/api/applications',{method:'PUT',body:{rows,expectedRows:applications.find(a=>a.student===identity)?.rows||null}});await refreshState();toast('지원 정보를 저장했습니다.');}catch(error){$('#applicationError').textContent=error.message;button.disabled=false;}};
}
function timelineScheduleView(students){
 const es=sorted(events.filter(e=>e.student===selected)),groupKey=e=>e.application||`legacy:${e.univ}:${e.major}`,groups=[...new Set(es.map(groupKey))],dates=[...new Set(es.map(e=>e.date))];
 return `<section class="card"><div class="card-head"><div><h2>대학별 일정 흐름</h2><p class="muted">위에서 아래로 날짜순 · 회색 일정은 1차 불합격으로 비활성화되었습니다.</p></div>${role==='학생'?`<span class="pill">${esc(current()?.name)}의 일정</span>`:`<select id="student" class="student-picker" aria-label="학생 선택">${students.map(s=>`<option value="${esc(s.id)}" ${selected===s.id?'selected':''}>${esc(s.number)} ${esc(s.name)}</option>`).join('')}</select>`}</div>${es.length?`<div class="timeline-wrap"><div class="timeline" style="grid-template-columns:90px repeat(${groups.length},minmax(190px,1fr))"><div class="th">날짜</div>${groups.map(g=>{const e=es.find(e=>groupKey(e)===g);return `<div class="th">${esc(e.univ)}<div class="muted" style="margin-top:8px;font-size:12px">${esc([e.admission,e.major,e.interviewType].filter(Boolean).join(' · '))}${e.direct?'<br>바로 면접 응시':''}</div></div>`;}).join('')}${dates.map(d=>`<div class="time-date">${Number(d.slice(5,7))}월 ${Number(d.slice(8))}일</div>${groups.map(g=>{const ue=es.filter(e=>groupKey(e)===g),active=d>=ue[0].date&&d<=ue[ue.length-1].date;return `<div class="timeline-cell ${active?'link':''}">${ue.filter(e=>e.date===d).map(e=>`<button class="milestone ${e.type} ${e.inactive?'inactive':''}" ${e.inactive?'disabled aria-disabled="true"':`data-event="${esc(e.id)}"`}>${kinds[e.type]}<small>${e.inactive?'1차 불합격 · 비활성':esc(e.result||e.time||'시간 미정')}</small></button>`).join('')}</div>`;}).join('')}`).join('')}</div></div>`:'<div class="empty">날짜가 등록된 대학 일정이 없습니다.</div>'}</section>`;
}

function lessonForm(existing,chosenDate){
 if(role==='학생')return;
 const classes=role==='관리자'?[...new Set(accounts.flatMap(classesOf))]:classesOf(current());if(!classes.length){toast('배정반 계정을 먼저 등록해주세요.');return;}
 const teacher=existing?.teacher_name||current()?.name,legacy=existing&&!existing.lesson_kind;
 showModal(existing?'방과후 수업 수정':'방과후 수업 등록',`<form id="lessonForm"><input type="hidden" name="type" value="lesson"><label>배정반<select name="class">${classes.map(c=>`<option ${(existing?.class||activeClass)===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>수업명<select name="lesson_kind">${legacy?`<option value="">${esc(existing.title)} (기존 수업)</option>`:''}${['1차-OT','2차-개별지도','3차-모의면접'].map(k=>`<option value="${k}" ${existing?.lesson_kind===k?'selected':''}>${k==='2차-개별지도'?esc(teacher)+' ':''}${k}</option>`).join('')}</select></label><fieldset class="target-box"><legend>대상</legend><label class="check-label"><input id="allTargets" type="checkbox"> 전체 <span id="targetCount" class="muted"></span></label><p class="muted">음영 표시된 학생은 해당 요일 참여가 어렵습니다. 필요하면 선택할 수 있습니다.</p><div id="targetGrid" class="target-grid"></div></fieldset><div class="actions"><label>날짜<input type="date" name="date" min="2000-01-01" max="2100-12-31" required value="${esc(existing?.date||chosenDate||localDate())}"></label><label>시간<select name="time" required>${existing?.time&&!['7교시','8교시','상시'].includes(existing.time)?`<option value="${esc(existing.time)}">기존 ${esc(existing.time)}</option>`:''}${['7교시','8교시','상시'].map(t=>`<option ${existing?.time===t?'selected':''}>${t}</option>`).join('')}</select></label></div><label>준비사항<textarea name="task" maxlength="5000" placeholder="수업 전에 준비할 내용을 적어주세요.">${esc(existing?.task||'')}</textarea></label><p id="lessonError" class="error" role="alert"></p><button class="primary" type="submit">${existing?'수정 저장':'수업 등록'}</button></form>`);
 const form=$('#lessonForm'),all=$('#allTargets');let full=existing?JSON.parse(existing.target_ids||'null')===null:false;
 const update=()=>{const boxes=[...form.querySelectorAll('[name="target"]')],count=boxes.filter(b=>b.checked).length;all.checked=full;all.indeterminate=!full&&count>0;$('#targetCount').textContent=`${count} / ${boxes.length}명 선택`;};
 const draw=(ids=[])=>{const list=accounts.filter(s=>s.role==='학생'&&s.class===form.elements.namedItem('class').value);$('#targetGrid').innerHTML=list.map(s=>`<label class="target-choice" data-target-id="${esc(s.id)}"><input name="target" type="checkbox" value="${esc(s.id)}" ${full||ids.includes(s.id)?'checked':''}><span><strong>${esc(s.name)}</strong><small>${esc(s.number)}</small><small class="unavailable-message"></small></span></label>`).join('')||'<p class="muted">이 반에 등록된 학생이 없습니다.</p>';form.querySelectorAll('[name="target"]').forEach(b=>b.onchange=()=>{full=false;update();});update();shadeLessonTargets(form);};
 all.onchange=()=>{full=all.checked;form.querySelectorAll('[name="target"]').forEach(b=>b.checked=full);update();};
 form.elements.namedItem('class').onchange=()=>{full=false;draw();};draw(JSON.parse(existing?.target_ids||'null')||[]);form.elements.namedItem('date').oninput=()=>shadeLessonTargets(form);
 form.onsubmit=async ev=>{ev.preventDefault();const data=Object.fromEntries(new FormData(form));data.target_ids=full?null:[...form.querySelectorAll('[name="target"]:checked')].map(b=>b.value);delete data.target;data.title=data.lesson_kind||existing?.title||'';if(data.target_ids&&!data.target_ids.length){$('#lessonError').textContent='대상 학생을 한 명 이상 선택해주세요.';return;}await saveEvent(form,existing,data);};
}
let resourcePosts=[],resourceLoading=false,resourceErrorMessage='';
function resourcesView(){return `<section class="card"><div class="card-head"><div><h2>공유 자료실</h2><p class="muted">교사·관리자가 올린 자료를 확인하세요. 열람 가능한 최근 200개 게시글을 표시합니다.</p></div>${role!=='학생'?'<button class="primary" id="writeResource">＋ 게시글 작성</button>':''}</div>${resourceLoading?'<div class="empty" role="status">자료를 불러오는 중입니다…</div>':resourceErrorMessage?`<div class="empty error" role="alert">${esc(resourceErrorMessage)}<br><button id="retryResources">다시 불러오기</button></div>`:resourcePosts.length?`<div class="resource-list">${resourcePosts.map(p=>`<button class="resource-row" data-resource="${esc(p.id)}"><span><strong>${esc(p.title)}</strong><small>${esc(p.author_name)} · ${new Date(p.created_at).toLocaleDateString('ko-KR')}</small></span><span class="pill">${p.files.length?'첨부 '+p.files.length+'개':'게시글'}</span></button>`).join('')}</div>`:'<div class="empty">열람 가능한 자료가 없습니다.</div>'}</section>`;}
async function loadResources(){resourceLoading=true;resourceErrorMessage='';render();try{resourcePosts=(await api('/api/resources')).posts;}catch(e){resourceErrorMessage=e.message;}finally{resourceLoading=false;if(user&&tab==='resources')render();}}
function bindResources(){if($('#writeResource'))$('#writeResource').onclick=()=>resourceForm();if($('#retryResources'))$('#retryResources').onclick=loadResources;document.querySelectorAll('[data-resource]').forEach(b=>b.onclick=()=>resourceDetail(b.dataset.resource));}
function resourceDetail(id){const p=resourcePosts.find(p=>p.id===id);if(!p)return;showModal(esc(p.title),`<p class="muted">${esc(p.author_name)} · ${new Date(p.created_at).toLocaleString('ko-KR')}</p><div class="task resource-body">${esc(p.content)}</div><div class="resource-files">${p.files.map(f=>`<a href="/api/resources/files/${encodeURIComponent(f.id)}" download>${esc(f.name)} <small>(${Math.ceil(f.size/1024)}KB)</small> ↓</a>`).join('')}</div>`,p.editable?'<button id="deleteResource" class="danger">삭제</button><button id="editResource">수정</button>':'');if(p.editable){$('#editResource').onclick=()=>resourceForm(p);$('#deleteResource').onclick=()=>{showModal('게시글 삭제',`<p>${esc(p.title)} 게시글과 첨부파일을 삭제하시겠습니까?</p>`,'<button id="cancelResourceDelete">취소</button><button id="confirmResourceDelete" class="danger">삭제</button>');$('#cancelResourceDelete').onclick=()=>resourceDetail(id);$('#confirmResourceDelete').onclick=async()=>{const b=$('#confirmResourceDelete');b.disabled=true;try{await api('/api/resources/'+id,{method:'DELETE',body:{}});$('#modal').close();await loadResources();toast('게시글을 삭제했습니다.');}catch(e){toast(e.message);b.disabled=false;}};};}}
function resourceForm(existing){if(role==='학생')return;
 showModal(existing?'게시글 수정':'게시글 작성',`<form id="resourceForm">${resourceAudienceView(existing)}<label>제목<input name="title" required maxlength="120" value="${esc(existing?.title||'')}"></label><label>내용<textarea name="content" maxlength="20000" rows="8" placeholder="공유할 자료에 대해 적어주세요.">${esc(existing?.content||'')}</textarea></label>${existing?'<p class="muted">첨부파일은 유지됩니다.</p>':'<label>파일 첨부<input name="files" type="file" multiple></label><p class="muted">최대 3개 · 합계 2MB 이하</p><p id="selectedFiles" class="muted"></p>'}<p id="resourceError" class="error" role="alert"></p><button class="primary" type="submit">${existing?'수정 저장':'게시글 등록'}</button></form>`);
 const form=$('#resourceForm');form.elements.namedItem('audience').onchange=()=>{$('#resourceTargetGrid').hidden=form.elements.namedItem('audience').value==='all';};if(!existing)form.elements.namedItem('files').onchange=e=>{$('#selectedFiles').textContent=[...e.target.files].map(f=>`${f.name} (${Math.ceil(f.size/1024)}KB)`).join(', ');};
 form.onsubmit=async ev=>{ev.preventDefault();const b=form.querySelector('[type="submit"]');b.disabled=true;$('#resourceError').textContent='';try{const data={title:form.elements.namedItem('title').value,content:form.elements.namedItem('content').value,target_ids:form.elements.namedItem('audience').value==='all'?null:[...form.querySelectorAll('[name="resourceTarget"]:checked')].map(c=>c.value)};if(data.target_ids&&!data.target_ids.length)throw Error('게시할 학생을 한 명 이상 선택해주세요.');if(!existing){const files=[...form.elements.namedItem('files').files];if(files.length>3||files.reduce((n,f)=>n+f.size,0)>2*1024*1024)throw Error('파일은 최대 3개, 합계 2MB 이하로 선택해주세요.');data.files=await Promise.all(files.map(f=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:f.name,data:String(reader.result).split(',')[1]});reader.onerror=()=>reject(Error('파일을 읽지 못했습니다.'));reader.readAsDataURL(f);})))}await api(existing?'/api/resources/'+existing.id:'/api/resources',{method:existing?'PUT':'POST',body:data});$('#modal').close();await loadResources();toast('게시글을 저장했습니다.');}catch(e){$('#resourceError').textContent=e.message;b.disabled=false;}};
}

const weekdayNames=['일','월','화','수','목','금','토'];
function availabilityFormView(){const a=availability.find(a=>a.student===identity)||{days:[],note:''};return `<section class="card availability-card"><form id="availabilityForm"><div class="card-head"><div><h2>방과후 일정 조정</h2><p class="muted">참여하기 어려운 요일과 특이사항을 담당 교사에게 알려주세요.</p></div><button type="submit" class="primary">조정 정보 저장</button></div><div class="availability-body"><fieldset class="weekday-options"><legend>안 되는 요일</legend>${[1,2,3,4,5].map(d=>`<label class="check-label"><input type="checkbox" name="days" value="${d}" ${a.days.includes(d)?'checked':''}>${weekdayNames[d]}요일</label>`).join('')}</fieldset><label>비고<textarea name="note" maxlength="2000" rows="4" placeholder="예: 화요일 학원 일정, 특정 날짜 참여 가능 등">${esc(a.note)}</textarea></label><p class="error" id="availabilityError" role="alert"></p></div></form></section>`;}
function bindAvailability(){const form=$('#availabilityForm');form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type="submit"]');button.disabled=true;$('#availabilityError').textContent='';try{const data=await api('/api/availability',{method:'PUT',body:{days:[...form.querySelectorAll('[name="days"]:checked')].map(c=>Number(c.value)),note:form.elements.namedItem('note').value}});availability=availability.filter(a=>a.student!==identity).concat(data);toast('방과후 조정 정보를 저장했습니다.');}catch(error){$('#availabilityError').textContent=error.message;}finally{button.disabled=false;}};}
function availabilityPanel(student){if(!student)return '';const a=availability.find(a=>a.student===student),s=accounts.find(a=>a.id===student);return `<section class="card availability-card"><div class="card-head"><h2>${esc(s?.name)} · 방과후 일정 조정</h2></div><div class="availability-body"><p><strong>안 되는 요일</strong>　${a?(a.days.length?a.days.map(d=>weekdayNames[d]+'요일').join(', '):'선택한 요일 없음'):'아직 입력하지 않았습니다.'}</p><h3>비고</h3><div class="task">${esc(a?.note||'등록된 특이사항이 없습니다.')}</div></div></section>`;}
function timelineView(students){return timelineScheduleView(students)+availabilityPanel(selected);}
function shadeLessonTargets(form){const value=form.elements.namedItem('date').value,d=value?new Date(value+'T12:00:00').getDay():-1;form.querySelectorAll('[data-target-id]').forEach(label=>{const a=availability.find(a=>a.student===label.dataset.targetId),unavailable=a?.days.includes(d);label.classList.toggle('unavailable',!!unavailable);label.querySelector('.unavailable-message').textContent=unavailable?`${weekdayNames[d]}요일 참여 어려움`:'';label.title=unavailable?'참여가 어려운 요일입니다. 필요하면 선택할 수 있습니다.':'';});}
function resourceAudienceView(existing){const ids=JSON.parse(existing?.target_ids||'null'),students=accounts.filter(a=>a.role==='학생'&&(role==='관리자'||classesOf(current()).includes(a.class)));return `<fieldset class="target-box"><legend>게시 대상</legend><label>공개 범위<select name="audience"><option value="all">전체 게시</option><option value="selected" ${ids!==null?'selected':''}>일부 학생 선택</option></select></label><div id="resourceTargetGrid" class="target-grid" ${ids===null?'hidden':''}>${students.map(s=>`<label class="target-choice"><input type="checkbox" name="resourceTarget" value="${esc(s.id)}" ${ids?.includes(s.id)?'checked':''}><span><strong>${esc(s.name)}</strong><small>${esc(s.class)} · ${esc(s.number)}</small></span></label>`).join('')||'<p class="muted">선택할 학생이 없습니다.</p>'}</div><p class="muted">일부 학생에게 게시하면 선택된 학생과 담당 교사·관리자가 열람할 수 있습니다.</p></fieldset>`;}

function isPrimaryCalendarEvent(e){
 if(role!=='교사'||['lesson','important'].includes(e.type))return true;
 const rows=applications.find(a=>a.student===e.student)?.rows||[],slot=rows.findIndex(r=>r.univ&&r.primary),chosen=slot>=0?slot:rows.findIndex(r=>r.univ);
 if(chosen>=0)return e.application?e.slot===chosen:e.univ===rows[chosen].univ&&e.major===rows[chosen].major;
 const first=events.find(a=>a.student===e.student&&!['lesson','important'].includes(a.type));return !first||e.univ===first.univ&&e.major===first.major;
}
function filteredCalendarEvents(list){return list.filter(e=>isPrimaryCalendarEvent(e)&&(e.type==='important'?true:showUniversity||e.type==='lesson')&&(role!=='교사'||showOtherTeachers||e.type!=='lesson'||!(e.lesson_kind==='2차-개별지도'||e.title?.includes('2차-개별지도'))||!e.teacher_id||e.teacher_id===identity));}
function calendarFilters(){return `<div class="calendar-filters" aria-label="달력 표시 설정">${role==='교사'?`<button id="toggleOtherTeachers" aria-pressed="${showOtherTeachers}" class="${showOtherTeachers?'selected':''}">다른 담당 교사 일정: ${showOtherTeachers?'표시':'숨김'}</button>`:''}<button id="toggleUniversity" aria-pressed="${showUniversity}" class="${showUniversity?'selected':''}">대학 일정: ${showUniversity?'표시':'숨김'}</button></div>`;}
function admissionResultForm(e){if(!['first','final'].includes(e.type)||e.inactive)return '';return `<form id="admissionResultForm" class="admission-result"><label>합격 여부<select name="result"><option value="" ${!e.result?'selected':''}>미정</option>${['합격','불합격'].map(r=>`<option ${e.result===r?'selected':''}>${r}</option>`).join('')}</select></label><p class="muted">${e.application?'저장하면 학생의 대학 일정 입력에도 반영됩니다.':'교사가 개별 등록한 발표 일정의 결과를 저장합니다.'}${e.type==='first'?'<br>1차 불합격이면 이후 면접·최종 발표 일정이 비활성화됩니다.':''}</p><p id="admissionResultError" class="error" role="alert"></p><button class="primary" type="submit">결과 저장</button></form>`;}
function bindAdmissionResult(e){if(!['first','final'].includes(e.type)||e.inactive)return;const form=$('#admissionResultForm');form.onsubmit=async ev=>{ev.preventDefault();const button=form.querySelector('[type="submit"]');button.disabled=true;$('#admissionResultError').textContent='';const body={student:e.student,phase:e.type,result:form.elements.namedItem('result').value,...(e.application?{slot:e.slot,expectedRow:applications.find(a=>a.student===e.student)?.rows[e.slot]}:{eventId:e.id,expectedResult:e.result||''})};try{await api('/api/results',{method:'POST',body});await refreshState();detail(e.id);toast('합격 여부를 저장했습니다.');}catch(error){$('#admissionResultError').textContent=error.message;button.disabled=false;}};}

function importantForm(existing){if(role==='학생')return;showModal(existing?'학사일정 수정':'학사일정 등록',`<form id="importantForm"><label>일정명<input name="title" required maxlength="100" value="${esc(existing?.title||'')}" placeholder="예: 수능, 학교재량휴업일"></label><label>날짜<input type="date" name="date" min="2000-01-01" max="2100-12-31" required value="${esc(existing?.date||localDate())}"></label><label>안내<textarea name="description" maxlength="2000" placeholder="필요한 안내를 적어주세요.">${esc(existing?.description||'')}</textarea></label><p class="muted">모든 교사와 학생의 달력에 학사일정으로 표시됩니다.</p><p id="importantError" class="error" role="alert"></p><button class="primary" type="submit">저장</button></form>`);$('#importantForm').onsubmit=async ev=>{ev.preventDefault();const form=ev.target,button=form.querySelector('[type="submit"]');button.disabled=true;try{const data=Object.fromEntries(new FormData(form));await api(existing?'/api/important-events/'+existing.id:'/api/important-events',{method:existing?'PUT':'POST',body:data});year=Number(data.date.slice(0,4));month=Number(data.date.slice(5,7))-1;$('#modal').close();await refreshState();toast('학사일정을 저장했습니다.');}catch(e){$('#importantError').textContent=e.message;button.disabled=false;}};}
function importantDetail(e){const editable=role==='관리자'||role==='교사'&&e.author_id===identity;showModal('학사일정',`<span class="pill important-pill">학사</span><h2 style="margin-top:16px">${esc(e.title)}</h2><p>${esc(e.date)} · 종일</p><div class="task">${esc(e.description||'등록된 안내가 없습니다.')}</div>`,editable?'<button id="deleteImportant" class="danger">삭제</button><button id="editImportant">수정</button>':'');if(editable){$('#editImportant').onclick=()=>importantForm(e);$('#deleteImportant').onclick=()=>{showModal('학사일정 삭제',`<p>${esc(e.title)} 일정을 삭제하시겠습니까?</p>`,'<button id="cancelImportant">취소</button><button id="confirmImportant" class="danger">삭제</button>');$('#cancelImportant').onclick=()=>importantDetail(e);$('#confirmImportant').onclick=async()=>{const b=$('#confirmImportant');b.disabled=true;try{await api('/api/important-events/'+e.id,{method:'DELETE',body:{}});$('#modal').close();await refreshState();toast('학사일정을 삭제했습니다.');}catch(error){toast(error.message);b.disabled=false;}};};}}
function lessonStage(e){const title=e.lesson_kind||e.title||'';return title.includes('1차')||title.includes('OT')?'1차-OT':title.includes('2차')||title.includes('개별지도')?'2차-개별지도':title.includes('3차')||title.includes('모의면접')?'3차-모의면접':'기타 수업';}
function lessonsForStudent(id,stage){const s=accounts.find(a=>a.id===id);return sorted(events.filter(e=>e.type==='lesson'&&e.class===s?.class&&(!stage||lessonStage(e)===stage)&&(JSON.parse(e.target_ids||'null')===null||JSON.parse(e.target_ids).includes(id))));}
function afterschoolView(){
 const students=accounts.filter(s=>s.role==='학생'&&(role==='관리자'||classesOf(current()).includes(s.class))&&(progressClass==='all'||progressClass===s.class)),stages=['1차-OT','2차-개별지도','3차-모의면접'];if(students.some(s=>lessonsForStudent(s.id,'기타 수업').length))stages.push('기타 수업');
 const classes=[...new Set(accounts.filter(a=>a.role==='학생'&&(role==='관리자'||classesOf(current()).includes(a.class))).map(a=>a.class))],registered=students.filter(s=>stages.slice(0,3).every(stage=>lessonsForStudent(s.id,stage).length)).length;
 return `<section class="card"><div class="card-head"><div><h2>학생별 방과후 등록 현황</h2><p class="muted">전체 ${students.length}명 · 1·2·3차 모두 등록 ${registered}명<br>각 차수에 등록된 수업을 날짜순으로 모두 표시합니다.</p></div><select id="progressClass" aria-label="방과후 조회 반"><option value="all">전체 배정반</option>${classes.map(c=>`<option ${progressClass===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="table-wrap"><table class="progress-table"><thead><tr><th>학생</th>${stages.map(stage=>`<th>${stage}</th>`).join('')}</tr></thead><tbody>${students.map(s=>`<tr><th><strong>${esc(s.name)}</strong><small>${esc(s.class)} · ${esc(s.number)}</small></th>${stages.map(stage=>{const list=lessonsForStudent(s.id,stage);return `<td>${list.length?`<strong>등록 ${list.length}회</strong>${list.map(e=>`<button class="progress-cell" data-event="${esc(e.id)}"><strong>${esc(e.date)} · ${esc(e.time)}</strong><small>${esc(e.title)}</small></button>`).join('')}`:'<span class="muted">미등록</span>'}</td>`;}).join('')}</tr>`).join('')}</tbody></table>${students.length?'':'<div class="empty">등록된 학생이 없습니다.</div>'}</div></section>`;
}
let submissionData={lessons:[],students:[],submissions:[]},submissionLoading=false,submissionMessage='',submissionClass='all',assignmentId='';
async function loadSubmissions(){submissionLoading=true;submissionMessage='';render();try{submissionData=await api('/api/submissions');}catch(e){submissionData={lessons:[],students:[],submissions:[]};submissionMessage=e.message;}finally{submissionLoading=false;if(user&&tab==='submissions')render();}}
function submissionLinks(s){return (s?.files||[]).map(f=>`<a class="submission-download" href="/api/submissions/files/${encodeURIComponent(f.id)}" download>${esc(f.name)} ↓</a>`).join('');}
function submissionsView(){
 if(submissionLoading)return '<section class="card empty" role="status">과제를 불러오는 중입니다…</section>';
 if(submissionMessage)return `<section class="card empty"><p class="error" role="alert">${esc(submissionMessage)}</p><button id="retrySubmissions">다시 불러오기</button></section>`;
 const classes=[...new Set(submissionData.students.map(s=>s.class))];if(submissionClass!=='all'&&!classes.includes(submissionClass))submissionClass='all';
 const lessons=submissionData.lessons.filter(e=>submissionClass==='all'||e.class===submissionClass);if(!lessons.some(e=>e.id===assignmentId))assignmentId=lessons[0]?.id||'';
 const lesson=lessons.find(e=>e.id===assignmentId),targets=lesson?submissionData.students.filter(s=>s.class===lesson.class&&(JSON.parse(lesson.target_ids||'null')===null||JSON.parse(lesson.target_ids).includes(s.id))):[],submitted=targets.filter(s=>submissionData.submissions.some(p=>p.event_id===assignmentId&&p.student===s.id)).length;
 return `<section class="card"><div class="card-head"><div><h2>${role==='학생'?'나의 과제':'우리 반 과제 제출 현황'}</h2><p class="muted">등록된 과제를 확인하세요. ${role==='학생'?'다시 제출하면 최신 제출물이 표시됩니다.':'반과 과제를 선택해 제출 여부와 파일을 확인하세요.'}</p></div><div class="actions">${role!=='학생'?'<button class="primary" id="createAssignment">＋ 과제등록</button>':''}<button id="retrySubmissions">새로고침</button></div></div><div class="submission-content"><div class="actions">${role!=='학생'?`<label>반<select id="submissionClass"><option value="all">전체 배정반</option>${classes.map(c=>`<option ${submissionClass===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label>`:''}<label>과제<select id="assignmentSelect">${lessons.map(e=>`<option value="${esc(e.id)}" ${e.id===assignmentId?'selected':''}>${esc(e.date)} · ${esc(e.class)} · ${esc(e.title)}</option>`).join('')}</select></label></div>${lesson?`<h3>${esc(lesson.title)}</h3>${lesson.editable?'<button id="editAssignment">과제 수정</button>':''}<p class="muted">${esc(lesson.date)} · ${esc(lesson.time)}</p><div class="task resource-body">${esc(lesson.task)}</div>${(lesson.files||[]).map(f=>`<a class="submission-download" href="/api/submissions/assignment-files/${encodeURIComponent(f.id)}" download>${esc(f.name)} ↓</a>`).join('')}${role==='학생'?studentSubmissionView(lesson):`<p><strong>제출 ${submitted}명 / 대상 ${targets.length}명</strong> · 미제출 ${targets.length-submitted}명</p><div class="table-wrap"><table><thead><tr><th>학번 · 이름</th><th>제출 여부</th><th>제출 글</th><th>첨부파일</th></tr></thead><tbody>${targets.map(s=>{const p=submissionData.submissions.find(p=>p.event_id===lesson.id&&p.student===s.id);return `<tr><th>${esc(s.number)} · ${esc(s.name)}</th><td>${p?`<span class="pill submitted">제출</span><small>${esc(new Date(p.created_at).toLocaleString('ko-KR'))}</small>`:'<span class="pill">미제출</span>'}</td><td>${p?`<button data-submission="${esc(p.id)}">내용 보기</button>`:'—'}</td><td>${p?submissionLinks(p)||'첨부 없음':'—'}</td></tr>`;}).join('')}</tbody></table></div>`}`:'<div class="empty">등록된 과제가 없습니다. 교사가 과제등록 버튼으로 과제를 추가하면 이곳에 표시됩니다.</div>'}</div></section>`;
}
function studentSubmissionView(lesson){const p=submissionData.submissions.find(s=>s.event_id===lesson.id&&s.student===identity);return `${p?`<section class="submitted-panel"><h3>최근 제출 · ${esc(new Date(p.created_at).toLocaleString('ko-KR'))}</h3><div class="resource-body">${esc(p.content)}</div>${submissionLinks(p)}</section>`:'<p class="muted">아직 제출하지 않았습니다.</p>'}<form id="submissionForm"><label>제출 글<textarea name="content" rows="6" maxlength="20000" placeholder="과제 내용이나 첨부파일에 대한 설명을 작성하세요.">${esc(p?.content||'')}</textarea></label><label>첨부파일<input name="files" type="file" multiple></label><p class="muted">최대 3개 · 합계 2MB 이하. 글 또는 파일을 제출하세요.${p?' 다시 제출할 때 파일도 새로 선택해주세요.':''}</p><p id="submissionError" class="error" role="alert"></p><button class="primary" type="submit">${p?'다시 제출':'과제 제출'}</button></form>`;}
function bindSubmissions(){
 if($('#createAssignment'))$('#createAssignment').onclick=()=>assignmentForm();
 if($('#editAssignment'))$('#editAssignment').onclick=()=>assignmentForm(submissionData.lessons.find(e=>e.id===assignmentId));
 if($('#retrySubmissions'))$('#retrySubmissions').onclick=loadSubmissions;
 if($('#submissionClass'))$('#submissionClass').onchange=e=>{submissionClass=e.target.value;assignmentId='';render();};
 if($('#assignmentSelect'))$('#assignmentSelect').onchange=e=>{assignmentId=e.target.value;render();};
 document.querySelectorAll('[data-submission]').forEach(b=>b.onclick=()=>{const p=submissionData.submissions.find(s=>s.id===b.dataset.submission),s=submissionData.students.find(s=>s.id===p?.student);if(p)showModal(esc(s?.name)+' · 제출 과제',`<p class="muted">${esc(new Date(p.created_at).toLocaleString('ko-KR'))}</p><div class="task resource-body">${esc(p.content||'첨부파일로 제출한 과제입니다.')}</div>${submissionLinks(p)}`);});
 const form=$('#submissionForm');if(role!=='학생'||!form)return;
 form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('[type="submit"]');b.disabled=true;$('#submissionError').textContent='';try{const files=[...form.elements.namedItem('files').files];if(files.length>3||files.reduce((sum,f)=>sum+f.size,0)>2*1024*1024)throw Error('파일은 최대 3개, 합계 2MB 이하로 선택해주세요.');const content=form.elements.namedItem('content').value;if(!content.trim()&&!files.length)throw Error('제출 글 또는 파일을 입력해주세요.');const attachments=await Promise.all(files.map(f=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:f.name,data:String(reader.result).split(',')[1]});reader.onerror=()=>reject(Error('파일을 읽지 못했습니다.'));reader.readAsDataURL(f);})));await api('/api/submissions',{method:'POST',body:{event:assignmentId,content,files:attachments}});await loadSubmissions();toast('과제를 제출했습니다.');}catch(error){$('#submissionError').textContent=error.message;b.disabled=false;}};
}
function assignmentForm(existing){
 if(role==='학생')return;
 const students=submissionData.students,classes=[...new Set(students.map(s=>s.class))];if(!classes.length){toast('학생 계정을 먼저 등록해주세요.');return;}
 showModal(existing?'과제 수정':'과제등록',`<form id="assignmentForm"><label>과제명<input name="title" maxlength="120" required value="${esc(existing?.title||'')}"></label><label>반<select name="class">${classes.map(c=>`<option ${submissionClass===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><fieldset class="target-box"><legend>학생선택</legend><label class="check-label"><input id="assignmentAll" type="checkbox"> 전체 선택</label><div class="target-grid" id="assignmentTargets"></div></fieldset><label>글쓰기<textarea name="content" maxlength="20000" rows="6" placeholder="과제 내용과 제출 안내를 작성해주세요.">${esc(existing?.task||'')}</textarea></label>${existing?`<fieldset class="target-box"><legend>기존 첨부파일 · 선택한 파일 유지</legend>${(existing.files||[]).map(f=>`<label class="check-label"><input type="checkbox" name="keepFile" value="${esc(f.id)}" checked>${esc(f.name)}</label>`).join('')}</fieldset>`:''}<label>첨부파일등록<input name="files" type="file" multiple></label><p class="muted">최대 3개 · 합계 2MB 이하</p><p id="assignmentError" class="error" role="alert"></p><button class="primary" type="submit">${existing?'수정 저장':'과제등록'}</button></form>`);
 const form=$('#assignmentForm'),all=$('#assignmentAll');const draw=(ids=[])=>{all.checked=false;all.indeterminate=false;$('#assignmentTargets').innerHTML=students.filter(s=>s.class===form.elements.namedItem('class').value).map(s=>`<label class="target-choice"><input type="checkbox" name="target" value="${esc(s.id)}" ${ids.includes(s.id)?'checked':''}><span>${esc(s.name)}<small>${esc(s.number)}</small></span></label>`).join('');form.querySelectorAll('[name="target"]').forEach(b=>b.onchange=()=>{const boxes=[...form.querySelectorAll('[name="target"]')];all.checked=boxes.every(b=>b.checked);all.indeterminate=!all.checked&&boxes.some(b=>b.checked);});const boxes=[...form.querySelectorAll('[name="target"]')];all.checked=boxes.length>0&&boxes.every(b=>b.checked);all.indeterminate=!all.checked&&boxes.some(b=>b.checked);};form.elements.namedItem('class').onchange=()=>draw();all.onchange=()=>{form.querySelectorAll('[name="target"]').forEach(b=>b.checked=all.checked);all.indeterminate=false;};draw(existing?(JSON.parse(existing.target_ids||'null')||students.filter(s=>s.class===existing.class).map(s=>s.id)):[]);
 form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type="submit"]');button.disabled=true;$('#assignmentError').textContent='';try{const target_ids=[...form.querySelectorAll('[name="target"]:checked')].map(b=>b.value);if(!target_ids.length)throw Error('학생을 한 명 이상 선택해주세요.');const files=[...form.elements.namedItem('files').files];if(files.length>3||files.reduce((sum,f)=>sum+f.size,0)>2*1024*1024)throw Error('파일은 최대 3개, 합계 2MB 이하로 선택해주세요.');const attachments=await Promise.all(files.map(f=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:f.name,data:String(reader.result).split(',')[1]});reader.onerror=()=>reject(Error('파일을 읽지 못했습니다.'));reader.readAsDataURL(f);})));const result=await api('/api/submissions/assignments'+(existing?'/'+existing.id:''),{method:existing?'PUT':'POST',body:{keep_files:existing?[...form.querySelectorAll('[name="keepFile"]:checked')].map(b=>b.value):[],title:form.elements.namedItem('title').value,class:form.elements.namedItem('class').value,content:form.elements.namedItem('content').value,target_ids,files:attachments}});assignmentId=result.id;$('#modal').close();await loadSubmissions();toast(existing?'과제를 수정했습니다.':'과제를 등록했습니다.');}catch(error){$('#assignmentError').textContent=error.message;button.disabled=false;}};
}
